import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a = 3
    let k = if a > 1 { 10 } else { 20 }
    io.println("if: ${k}")
    let j = if a > 5 { 1 } else if a > 2 { 2 } else { 3 }
    io.println("chain: ${j}")
    let b = { a + 1 }
    io.println("blk: ${b}")
    let r = scope timeout(1000) { 5 }
    let n = match r {
        Ok(_) => 5
        Err(_) => 0 - 1
    }
    io.println("match: ${n}")
    return Ok(())
}
